// Re-run both Git baseline and current public routes; hash original serialized bytes.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {createHash}=require('node:crypto');
const root=path.resolve(__dirname,'../..'),base=process.argv[2];
assert(base,'usage: node tests/fixtures/record-opening-live.cjs <baseline export>');
const sha=b=>createHash('sha256').update(b).digest('hex');
function bytes(a,b){const x=Buffer.from(a),y=Buffer.from(b);let n=0;while(n<Math.min(x.length,y.length)&&x[n]===y[n])n++;return {previousBytes:x.length,currentBytes:y.length,previousSha256:sha(x),currentSha256:sha(y),byteEqual:x.equals(y),firstByteOffset:x.equals(y)?null:n};}
async function main(){const {createServer}=await import('vite'),servers=[];
try{for(const directory of [base,root])servers.push(await createServer({root:directory,configFile:false,server:{middlewareMode:true,ws:false},appType:'custom',logLevel:'error'}));
const engines=[];for(const server of servers)engines.push({h:await server.ssrLoadModule('/tests/fixtures/t13-loot-public.ts'),api:await server.ssrLoadModule('/src/simulation/match.ts'),ser:await server.ssrLoadModule('/src/simulation/serialization.ts')});
const audit={baselineCommit:'94eecbcbfbce72d4740923b8c793c66c483bfd51',method:'Both engines execute original public helpers. No state fields are patched. Every captured state strictly restores as text and object.',cases:[]};
const scenarios={transfer:e=>e.h.transferPreparation(),terminal:e=>e.h.terminalPreparation(null),reveal:e=>e.h.publicPrefix('4-7',42,'mage'),capacity:async e=>e.h.fillBench(await e.h.publicPrefix('3-7',36),['tristana']),growth:async(e,index)=>{const p=await e.h.configuredPrefix('3-7',{seed:48,build:'cannon',copyLimits:{tristana:2},fieldCopies:['tristana']});const ids=p.preparation.units.filter(u=>u.definitionId==='tristana'&&u.starLevel===1).map(u=>u.id).sort();assert.equal(ids.length,2);let s=e.h.accepted(e.api.deployMatchUnit(e.h.reserveExcept(p,ids),ids[0],{kind:'board',cell:{col:0,row:4}}));if(index===1)s=e.h.accepted(e.api.deployMatchUnit(s,ids[0],{kind:'board',cell:{col:6,row:7}}));return s;}};
for(const [name,scenario]of Object.entries(scenarios)){console.log('Recording '+name);const states=[];for(let i=0;i<2;i++)states.push(await scenario(engines[i],i));const battles=states.map((s,i)=>engines[i].h.battle(s));for(let i=0;i<2;i++)for(const s of [states[i],battles[i].started,battles[i].revealed,battles[i].ended].filter(Boolean)){const raw=engines[i].ser.serializeMatch(s);assert.deepEqual(engines[i].ser.restoreMatch(raw),s);assert.deepEqual(engines[i].ser.restoreMatch(JSON.parse(raw)),s);}
const summary=(s,b)=>({gold:s.gold,hp:s.playerHp,nextUnitSerial:s.nextUnitSerial,units:s.preparation.units.map(u=>({id:u.id,hero:u.definitionId,star:u.starLevel,location:u.location})),growth:s.persistentGrowth,deathTicks:b.ended.combat.neutralReceipts.deaths.map(d=>d.tick),growthEvents:b.events.filter(e=>e.type==='growth'),upgrades:b.events.filter(e=>e.type==='unitUpgraded')});
audit.cases.push({name,preparation:bytes(...states.map((s,i)=>engines[i].ser.serializeMatch(s))),events:bytes(...battles.map(b=>JSON.stringify(b.events))),final:bytes(...battles.map((b,i)=>engines[i].ser.serializeMatch(b.ended))),previous:summary(states[0],battles[0]),current:summary(states[1],battles[1]),strictTextAndObjectRestore:true});}
audit.sources=['tests/fixtures/t13-loot-public.ts','tests/m8-b8-live-growth.test.ts','tests/m8-b8-live-capacity.test.ts','tests/m8-b8-live-transfer.test.ts','tests/m8-b8-live-reveal.test.ts'].map(file=>({file,...bytes(fs.readFileSync(path.join(base,file)),fs.readFileSync(path.join(root,file)))}));
fs.writeFileSync(path.join(root,'docs/evidence/opening-random/live-migration.json'),JSON.stringify(audit,null,2)+'\n');console.log(JSON.stringify({passed:true,cases:audit.cases.length}));
}finally{for(const s of servers)await s.close();}}
main().catch(e=>{console.error(e);process.exitCode=1});
